          "model_answer": "A primary reason for the rapid de-industrialisation of Indian textiles was the flood of cheap, machine-made British cloth. Following the Industrial Revolution, mills in Lancashire produced vast quantities of cheap cotton cloth using steam-powered looms, undercutting traditional Indian handloom weavers.<br><br>Furthermore, British colonial tariffs systematically dismantled local manufacturing. The East India Company and British Parliament placed heavy duties on Indian woven silk and calico entering Britain, while forcing India to import British manufactured goods duty-free. Consequently, millions of skilled Indian weavers lost their livelihoods, turning India into an exporter of raw cotton.",
