      "vocab_cloze_text": "The legacy of the British Empire remains at the centre of fierce [Historiography] among modern historians. Writers associated with the [Optimist School] highlight global trade networks, railways, and administrative institutions, whereas critics in the [Pessimist School] emphasise famine, violent conquest, and economic coercion. Indian nationalist Dadabhai Naoroji formulated [Drain Theory] to show how colonial taxation transferred billions in wealth from India to Britain, while scholars in [Subaltern Studies] examine empire from the viewpoint of ordinary colonised people so students can reach a reasoned [Synthesis].",
