      "extract": "The Great Exhibition of 1851 at the Crystal Palace celebrated Britain as the undisputed Workshop of the World. Six million visitors marvelled at hydraulic presses, electric telegraphs, and Indian diamonds. Yet in the shadows of this imperial triumph lay two starkly contrasting balance sheets.<br><br>To the Optimists, the 19th-century transformation was a triumphant march of progress: real wages eventually rose, railways united continents, cholera was conquered by clean sewers, and parliamentary democracy expanded from rotten boroughs to mass secret ballots.<br><br>To the Pessimists and anti-colonial scholars, that glittering wealth came at an intolerable moral price: three generations of British factory children worked to exhaustion in unventilated mills, unsewered industrial cellars killed labourers before the age of twenty, and across India and Africa, ancient cultures and artisanal industries were dismantled to feed European industrial syndicates.",
